def habilitar_desabilitar_indices(table_name, operation):
    '''
        Método que desabilita ou habilita todos os índices de determinada tabela.

        Obs: Neste método nós não realizamos um commit ao final porque toda a migration já roda dentro de uma transação.
        Então, no caso de uma tabela ter seus índices desabilitados e logo após ocorrer um erro, esse ajuste também será
        desfeito, ou seja, os índices voltaram ao estado original (habilitado).
    '''
    msg_inicial = ''
    msg_final = ''
    indisready = ''
    if (operation == 'ENABLE'):
        indisready = 'true'
        msg_inicial = f'Habilitando os índices da tabela {table_name}.'
        msg_final = f'Habilitação de índices concluída {table_name}.'
    elif (operation == 'DISABLE'):
        indisready = 'false'
        msg_inicial = f'Desabilitado os índices da tabela {table_name}.'
        msg_final = f'Desabilitação de índices concluída {table_name}.'
    else:
        raise Exception('Parâmetro inválido.')

    sql = f'''
        UPDATE 	pg_index
        SET 	indisready = {indisready}
        WHERE 	indrelid = 	(
                                SELECT  oid
                                FROM    pg_class
                                WHERE   relname='{table_name}'
                            );
    '''
    cur = connection.cursor()
    print(msg_inicial)
    cur.execute(sql)
    if (operation == 'ENABLE'):
        print(f'Reindexando índices da tabela {table_name}...')
        cur.execute(f'REINDEX TABLE {table_name};')
    print(msg_final)


def migrar_id_pessoa_para_secret_vinculo(apps, schema):
    start_time_all = datetime.datetime.now()
    Vinculo = apps.get_model('comum.Vinculo')

    print("\n Atualizando Vinculo \n")
    start_time_partial = datetime.datetime.now()
    habilitar_desabilitar_indices(table_name='comum_vinculo', operation='DISABLE')
    Vinculo.objects.filter(secret__isnull=True).update(secret=F('pessoa_id'), skip_history=True)
    habilitar_desabilitar_indices(table_name='comum_vinculo', operation='ENABLE')
    print(f'Duration: {datetime.datetime.now() - start_time_partial}')

    print(f'Total Duration: {datetime.datetime.now() - start_time_all}')


